// NewGroup returns a new Group.
func NewGroup(logger *zap.Logger, ctxs ...context.Context) Group {
	g := &group{
		logger:       logger,
		panicHandler: nil, // Set separately by SetPanicHandler
		wg:           sync.WaitGroup{},

		errMutex: sync.Mutex{},
		err:      nil,
	}
	if len(ctxs) > 0 {
		g.SetContext(ctxs[0])
	}
	return g
}

// Context returns the Context associated with the Group, if any.
func (g *group) Context() context.Context {
	return g.ctx
}

// SetContext updates the current Group with an associated Context.
// The context will be canceled if any goroutine returns an error.
// See https://pkg.go.dev/golang.org/x/sync/errgroup#WithContext
func (g *group) SetContext(ctx context.Context) context.Context {
	g.ctx, g.cancel = context.WithCancel(ctx)
	return g.ctx
}

// WithContext updates the current Group with an associated Context.
//
// Deprecated: use NewGroup with a context argument, SetContext, and Context instead.
func (g *group) WithContext(ctx context.Context) context.Context {
	return g.SetContext(ctx)
}

// SetPanicHandler sets a panic handler for the group.
func (g *group) SetPanicHandler(f func(any)) {
	g.panicHandler = f
}

// WithPanicHandler sets a panic handler for the group.
//
// Deprecated: use SetPanicHandler instead.
func (g *group) WithPanicHandler(f func(any)) {
	g.SetPanicHandler(f)
}
